std::set<int> s;

// Underlying structure: Self-balancing Binary Search Tree (typically Red-Black Tree)
// Key is compared via std::less<T> (default comparator)

// O(log N) complexity for search and insertion
auto [it, success] = s.insert(42);

// Return type: std::pair<iterator, bool>
// success == true if element was newly inserted

// Attempting duplicate insertion: Uniqueness constraint enforced
// success == false; it points to the existing node (42)
s.insert(42);

// Insertion with hint (if key is near 'it', can be O(1) amortized)
s.insert(s.begin(), 10);

// Emplace construction avoids temporary object creation
s.emplace(100);
